-- Palms Off Gaming binders: schema support + the eight binder products.
--
-- Stage 1 is one product per binder line, listed against its hero (Black)
-- photography. Each line also ships in the colours recorded in
-- data/shopBinderProducts.js; those become their own products in a later pass.
--
-- Three parts:
--   1. Make the product-photo bucket public. The images live in the
--      `palms off gaming products` Storage bucket, which was created private.
--      Product photography has to be anonymously readable or the pages render
--      broken images and Google indexes none of them — a private bucket only
--      serves signed URLs, which expire and are never cached by the image
--      Worker (it proxies /object/public/ only). See docs/image-cdn.md.
--   2. Add `brand` and `sku` to shop_products, and make `slug` unique. The
--      /shop/binders/<slug> pages look products up by slug, so a duplicate
--      slug would make which row wins arbitrary.
--   3. Seed the eight products as `draft`.
--
-- The rows are seeded as status 'draft' with a price of 0 deliberately: prices
-- have not been set yet, and these binders are enquiry-only for now (the
-- product page's CTA sends visitors to /signup rather than to a checkout).
-- Draft keeps them out of the shop grid, which filters status = 'active', so
-- nothing shows up listed at $0.00. The /shop/binders pages are unaffected —
-- they render from data/shopBinderProducts.js and stay indexable — but no
-- Offer is emitted in their JSON-LD until a real price is set and the row is
-- switched to 'active' in /admin/products.
--
-- Idempotent: keyed on the unique slug, so re-running is a no-op and never
-- overwrites prices or stock edited in the admin portal.

-- ── 1. Public read on the product photo bucket ──────────────────────────────
update storage.buckets
set public = true
where id = 'palms off gaming products';

-- ── 2. Schema ───────────────────────────────────────────────────────────────
alter table public.shop_products add column if not exists brand text;
alter table public.shop_products add column if not exists sku text;

create unique index if not exists shop_products_slug_key
  on public.shop_products (slug)
  where slug is not null;

-- ── 3. Seed ─────────────────────────────────────────────────────────────────
insert into public.shop_products
  (title, slug, sku, description, images, brand, category, product_type, price_aud, stock_quantity, status)
select
  v.title, v.slug, v.sku, v.description, v.images::jsonb,
  'Palms Off Gaming', 'Binders', 'accessory', 0, 0, 'draft'
from (values
  ('Palms Off Gaming Collector''s Series 4-Pocket Zip Binder', 'palms-off-gaming-collectors-series-4-pocket-zip-binder', 'ZB-04', 'The 4-pocket Collector''s Series zip binder from Palms Off Gaming — side-loading archival pockets, a padded PU leather cover and a full metal zip. Eight colours, shipped Australia-wide.', '["https://vrfsaazuqjxotnieqlkd.supabase.co/storage/v1/object/public/palms%20off%20gaming%20products/BINDERS/Collectors%20series%204%20pocket/Black/ZB-04-BLK_collectors-series-4-pocket-zip-binder-black_front.png","https://vrfsaazuqjxotnieqlkd.supabase.co/storage/v1/object/public/palms%20off%20gaming%20products/BINDERS/Collectors%20series%204%20pocket/Black/ZB-04-BLK_collectors-series-4-pocket-zip-binder-black_profile.png","https://vrfsaazuqjxotnieqlkd.supabase.co/storage/v1/object/public/palms%20off%20gaming%20products/BINDERS/Collectors%20series%204%20pocket/Black/ZB-04-BLK_collectors-series-4-pocket-zip-binder-black_spread.png","https://vrfsaazuqjxotnieqlkd.supabase.co/storage/v1/object/public/palms%20off%20gaming%20products/BINDERS/Collectors%20series%204%20pocket/Black/ZB-04-BLK_collectors-series-4-pocket-zip-binder-black_interior.png","https://vrfsaazuqjxotnieqlkd.supabase.co/storage/v1/object/public/palms%20off%20gaming%20products/BINDERS/Collectors%20series%204%20pocket/Black/ZB-04-BLK_collectors-series-4-pocket-zip-binder-black_pockets.png","https://vrfsaazuqjxotnieqlkd.supabase.co/storage/v1/object/public/palms%20off%20gaming%20products/BINDERS/Collectors%20series%204%20pocket/Black/ZB-04-BLK_collectors-series-4-pocket-zip-binder-black_zipper.png","https://vrfsaazuqjxotnieqlkd.supabase.co/storage/v1/object/public/palms%20off%20gaming%20products/BINDERS/Collectors%20series%204%20pocket/Black/ZB-04-BLK_collectors-series-4-pocket-zip-binder-black_logo.png","https://vrfsaazuqjxotnieqlkd.supabase.co/storage/v1/object/public/palms%20off%20gaming%20products/BINDERS/Collectors%20series%204%20pocket/Black/ZB-04-BLK_collectors-series-4-pocket-zip-binder-